export type ParsedSettleInstruction<
  TProgram extends string = typeof RUIN_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    house: TAccountMetas[1];
    table: TAccountMetas[2];
    quoteMint: TAccountMetas[3];
    vault: TAccountMetas[4];
    tokenProgram: TAccountMetas[5];
    destination?: TAccountMetas[6] | undefined;
    trader: TAccountMetas[7];
    feed: TAccountMetas[8];
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
  };
  data: SettleInstructionData;
};

export function parseSettleInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === RUIN_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      house: getNextAccount(),
      table: getNextAccount(),
      quoteMint: getNextAccount(),
      vault: getNextAccount(),
      tokenProgram: getNextAccount(),
      destination: getNextOptionalAccount(),
      trader: getNextAccount(),
      feed: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getSettleInstructionDataDecoder().decode(instruction.data),
  };
}
